			{
				if (fabs(overlapOn1[j].dot(normal) + distance) > tolerance)
					return false;
			}
		}

		return true;
	}

	bool Face::fuzzyContainsInExtrusion(const G3D::Vector3& point, float tolerance) const
	{
		RBXASSERT(tolerance >= 0.0);

