	{
		min = 1.0e10;
		max = -1.0e10;

		for (int i = 0; i < 4; ++i)
		{
			const G3D::Vector3& v = (*this)[i];
			float temp = (v - point).dot(normal);
			min = G3D::min(min, temp);
			max = G3D::max(max, temp);
